function numDecodings(s) {
  const MOD = 1000000007;
  const one = (ch) => (ch === '*' ? 9 : ch === '0' ? 0 : 1);
  const two = (first, second) => {
    if (first === '*' && second === '*') return 15;
    if (first === '*') return second <= '6' ? 2 : 1;
    if (second === '*') return first === '1' ? 9 : first === '2' ? 6 : 0;
    const value = Number(first + second);
    return value >= 10 && value <= 26 ? 1 : 0;
  };
  let before = 1;
  let current = one(s[0]);
  for (let i = 1; i < s.length; i++) {
    const next = (one(s[i]) * current + two(s[i - 1], s[i]) * before) % MOD;
    before = current;
    current = next;
  }
  return current;
}

