function numDecodings(s) {
  // Fill a table from the back, trying every concrete digit a character can be.
  const MOD = 1000000007;
  const choices = ch => (ch === '*' ? [1, 2, 3, 4, 5, 6, 7, 8, 9] : [Number(ch)]);
  const ways = new Array(s.length + 1).fill(0);
  ways[s.length] = 1;
  for (let i = s.length - 1; i >= 0; i--) {
    let total = 0;
    for (const d of choices(s[i])) {
      if (d === 0) continue;
      total = (total + ways[i + 1]) % MOD;
      if (i + 1 < s.length) {
        for (const e of choices(s[i + 1])) if (d * 10 + e <= 26) total = (total + ways[i + 2]) % MOD;
      }
    }
    ways[i] = total;
  }
  return ways[0];
}

