function generate(rand, size) {
  const n = size === 'large' ? 9000 + Math.floor(rand() * 1001) : 1 + Math.floor(rand() * 8);
  const pool = rand() < 0.3 ? '**12' : '*0123456789*12*';
  let s = '';
  for (let i = 0; i < n; i++) s += pool[Math.floor(rand() * pool.length)];
  return [s];
}
